<div class="top"><div><h2 style="margin:0">Inventory</h2><span class="muted">Stock value (items with a unit cost): <?= e(money($value)) ?></span></div><?php if (can('stock.manage')): ?><a class="btn" href="/staff/inventory/new">+ New item</a><?php endif; ?></div>
<form class="filters" method="get"><div><label>Search</label><input name="q" value="<?= e($q) ?>" placeholder="name, SKU, colour, supplier"></div>
<div><label>Category</label><select name="cat" data-autosubmit><option value="">All</option><?= options(STOCK_CATEGORIES, $cat) ?></select></div>
<label style="margin:0 0 14px"><input type="checkbox" name="low" value="1" <?= $low ? 'checked' : '' ?> style="width:auto;margin:0 6px 0 0" data-autosubmit>Low stock only</label><button class="btn alt sm">Apply</button></form>
<div class="card"><div class="tw"><table><tr><th>Item</th><th>Category</th><th>Material / colour</th><th class="right">In stock</th><th class="right">Reorder at</th><th>Location</th><th>Supplier</th><th></th></tr>
<?php foreach ($rows as $r): ?><tr><td><a href="/staff/inventory/<?= (int) $r['id'] ?>"><?= e($r['name']) ?></a><?= $r['sku'] ? ' <span class="muted">' . e($r['sku']) . '</span>' : '' ?></td><td><?= e(STOCK_CATEGORIES[$r['category']]) ?></td><td><?= e(trim(($r['material'] ?? '') . ' ' . ($r['color'] ?? ''))) ?: '—' ?></td>
<td class="right <?= inv_low($r) ? 'overdue' : '' ?>"><?= e(rtrim(rtrim($r['qty'], '0'), '.') ?: '0') ?> <?= e($r['unit']) ?></td><td class="right"><?= e(rtrim(rtrim($r['reorder_level'], '0'), '.') ?: '0') ?></td><td><?= e($r['location'] ?? '—') ?></td><td><?= e($r['supplier'] ?? '—') ?></td><td><?= inv_low($r) ? badge('Reorder', 'p-bad') : '' ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="8" class="muted">No items found.</td></tr><?php endif; ?></table></div></div>
